    {
      "name": "unclamp_pressure_limit",
      "value": "1.00",
      "units": "kPa(g)",
      "narrative_section": "4.7"
    },
    {
      "name": "overpressure_trip",
      "value": "20.00",
      "units": "kPa(g)",
      "narrative_section": "4.8"
    },
    {
      "name": "pt_fault_below",
      "value": "-5.00",
      "units": "kPa(g)",
      "narrative_section": "4.8"
    },
    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "CLAMP (M201)",
      "entry": "Pallet in position rising edge (ZS-2008 / X23), Auto mode (SS-0003 / X2), no active ST20 fault (ANI M299), station idle (ANI M200).",
      "exit": "Clamp confirmed closed (ZS-2002A / X20) and clamp open clear (ANI ZS-2002B / X21)."
    },
    {
      "name": "FILL (M202)",
      "entry": "Clamp confirmed closed and clamp open clear.",
      "exit": "PT-2001 pressure reaching fill completion threshold (D100 >= D122, 14.50 kPa) OR fill timeout (T21, 8.0 s) / fault trip."
    },
    {
      "name": "STABILISE (M203)",
      "entry": "Fill threshold reached (D100 >= D122).",
      "exit": "Stabilisation timer complete (T22)."
    },
    {
      "name": "TEST (M204)",
      "entry": "Stabilisation timer done (T22).",
      "exit": "Test window timer complete (T23, 10.0 s)."
    },
    {
      "name": "VENT (M205)",
      "entry": "Test window complete (T23) OR fault trip during busy state (M299 AND M200).",
      "exit": "Vent time elapsed (0.5 s), pressure below 1.00 kPa (D100 < K100), and PT-2001 healthy (ANI M292)."
    },
    {
      "name": "UNCLAMP (M206)",
      "entry": "Vent condition met (vent timer done, D100 < 1.00 kPa, PT-2001 healthy).",
      "exit": "Clamp confirmed open (ZS-2002B / X21) and clamp closed clear (ANI ZS-2002A / X20)."
    },
    {
      "name": "DONE (M207)",
      "entry": "Clamp confirmed open (ZS-2002B / X21 and ANI ZS-2002A / X20).",
      "exit": "Pallet leaves test position (ANI ZS-2008 / X23)."
    }
  ],
  "interlocks": [
    {
      "cause": "Clamp not confirmed closed (ZS-2002A / X20 lost or ZS-2002B / X21 made)",
      "effect": "Fill valve XV-2003 (Y21) cannot open and closes immediately."
    },
    {
      "cause": "ST20 fault active (M299) or E-stop lost (X0)",
      "effect": "Fill valve XV-2003 (Y21) inhibited; active test aborts to VENT (M205) with FAIL result (M211)."
    },
    {
      "cause": "Overpressure condition detected (PT-2001 / D100 > D123, 20.00 kPa)",
      "effect": "Fill valve XV-2003 closed, vent valve XV-2004 (Y22) held open, FAIL result latched."
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault (M292)",
      "effect": "Unclamp inhibited; station held in VENT with vent valve held open."
    },
    {
      "cause": "ST20 station busy (M200)",
      "effect": "New cycle start inhibited if pallet sensor drops and returns."
    },
    {
      "cause": "Manual vent pushbutton (PB-2010 / X25) pressed while not in auto mode (ANI X2)",
      "effect": "Vent valve XV-2004 (Y22) opens manually."
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout (M290)",
      "condition": "Test pressure (14.50 kPa) not reached within fill timeout period (T21, 8.0 s) during FILL (M202)",
      "action": "Sets latched alarm M290, aborts cycle to VENT (M205), asserts FAIL (M211), and lights fault beacon HL-2011 (Y25)."
    },
    {
      "name": "Over-pressure (M291)",
      "condition": "PT-2001 pack pressure D100 exceeds overpressure limit D123 (20.00 kPa / K2000)",
      "action": "Sets latched alarm M291, opens vent valve XV-2004 (Y22), closes fill valve XV-2002, aborts sequence to VENT with FAIL result, and lights fault beacon HL-2011 (Y25)."
    },
    {
      "name": "PT-2001 signal fault (M292)",
      "condition": "PT-2001 reading D100 falls below -5.00 kPa (K-500) indicating wire break",
      "action": "Activates unlatched alarm M292, inhibits cycle start, prevents transition to UNCLAMP holding vent open, and triggers fault summary M299 / beacon HL-2011 (Y25)."
    },
    {
      "name": "Supply air low (M293)",
      "condition": "Supply air pressure switch PS-2009 (X22) lost while station is busy (M200)",
      "action": "Sets latched alarm M293, aborts cycle to VENT (M205) with FAIL result (M211), and lights fault beacon HL-2011 (Y25)."
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s (Narrative §4.4)",
      "parameter_sheet_says": "5.0 s (T22, changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (R13: OUT T22 K50)",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s (Narrative §4.7)",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (R21 uses OUT T200 K50, which is 100 ms per tick on FX5, running for 5.0 s instead of 0.5 s due to FX3 migration trap)",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "baseline_pressure_sample_timing",
      "narrative_says": "Baseline pressure recorded at end of stabilisation (§4.4)",
      "parameter_sheet_says": "stabilise_time 5.0 s (T22), test_window 10.0 s (T23)",
      "program_says": "R14 samples baseline pressure D110 on T23 done contact rather than T22 done",
      "authoritative": "parameter_sheet"
    }
  ]
}
